mapper.select:

            select 
            /*+ index_asc(item SYS_C007008) */
            ino, category, name, price, amount, discount, content, regDate
			from (
				select 
					/*+ index_asc(item SYS_C007008) */
					rownum rn, ino, category, name, price, amount, discount, content, regDate
					from item
					where 1 = 1
					and ino > 0





						and rownum <= #{pageNum} * #{amount}




				 )
			where 1 = 1
			and rn > (#{pageNum} - 1) * #{amount}

mapper.update:

         	update item set
			amount = amount + #{amount}
			where 1 = 1
			and ino = #{ino}

mapper.delete:

delete from item
where 1 = 1
and ino = #{ino}
